import fs from "node:fs";

import { expect, sample, test, uniqueName } from "../../fixtures";

const UPLOADS = [
  { kind: "w9", file: "w9.txt" },
  { kind: "insurance_certificate", file: "insurance_certificate.txt" },
  { kind: "contract", file: "contract.txt" },
] as const;

test("submitting a vendor with all documents extracted moves it to review", { tag: "@REV-01" }, async ({ apiAs }) => {
  const member = await apiAs("member");

  // Arrange: a draft vendor
  const createRes = await member.post("/api/vendors", {
    data: {
      name: uniqueName("REV-01 Vendor"),
      category: "services",
      contact_email: `rev01.${Date.now().toString(36)}${Math.random().toString(36).slice(2, 6)}@example.com`,
    },
  });
  expect(createRes.status(), await createRes.text()).toBe(201);
  const vendor = (await createRes.json()) as { id: string; status: string };
  expect(vendor.status).toBe("draft");

  // Arrange: upload all three required documents
  for (const upload of UPLOADS) {
    const uploadRes = await member.post(`/api/vendors/${vendor.id}/documents`, {
      multipart: {
        kind: upload.kind,
        file: {
          name: upload.file,
          mimeType: "text/plain",
          buffer: fs.readFileSync(sample(upload.file)),
        },
      },
    });
    expect(uploadRes.status(), await uploadRes.text()).toBe(201);
  }

  // Arrange: wait for background extraction of every document
  await expect
    .poll(
      async () => {
        const listRes = await member.get(`/api/vendors/${vendor.id}/documents`);
        expect(listRes.status(), await listRes.text()).toBe(200);
        const docs = (await listRes.json()) as { kind: string; status: string }[];
        return docs.length === UPLOADS.length && docs.every((d) => d.status === "extracted");
      },
      { timeout: 30_000, intervals: [500, 1000] },
    )
    .toBe(true);

  // Act
  const submitRes = await member.post(`/api/vendors/${vendor.id}/submit`);

  // Assert
  expect(submitRes.status(), await submitRes.text()).toBe(200);
  const submitted = (await submitRes.json()) as { status: string; submitted_at: string | null };
  expect(submitted.status, JSON.stringify(submitted)).toBe("in_review");
  expect(submitted.submitted_at, JSON.stringify(submitted)).not.toBeNull();

  const auditRes = await member.get(`/api/vendors/${vendor.id}/audit`);
  expect(auditRes.status(), await auditRes.text()).toBe(200);
  const audit = (await auditRes.json()) as { items: { action: string }[] };
  expect(
    audit.items.map((e) => e.action),
    JSON.stringify(audit),
  ).toContain("vendor.submitted");
});
